int main(int argc, char **argv)
{
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return 1;
    }

    const char *input_path = argv[1];
    FILE *fp = fopen(input_path, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s\n", input_path);
        return 1;
    }

    struct csv_parser parser;
    memset(&parser, 0, sizeof(parser));
    if (csv_init(&parser, 1) != 0) {
        fprintf(stderr, "csv_init failed\n");
        fclose(fp);
        return 1;
    }

    unsigned char buf[4096];
    size_t total_bytes = 0;
    int ok = 1;
    struct timespec t0;
    struct timespec t1;

    if (get_now(&t0) != 0) {
        fprintf(stderr, "time start failed\n");
        csv_free(&parser);
        fclose(fp);
        return 1;
    }

    while (1) {
        size_t got = fread(buf, 1, sizeof(buf), fp);
        if (got == 0) {
            if (ferror(fp)) {
                fprintf(stderr, "Read failed\n");
                ok = 0;
            }
            break;
        }

        size_t consumed = csv_parse(&parser, buf, got, NULL, NULL, NULL);
        total_bytes += consumed;
        if (consumed != got) {
            ok = 0;
            fprintf(stderr, "Malformed CSV at byte %zu (csv_error=%d)\n",
                    total_bytes + 1, csv_error(&parser));
            break;
        }
    }

    if (ok && csv_fini(&parser, NULL, NULL, NULL) != 0) {
        ok = 0;
        fprintf(stderr, "csv_fini failed (csv_error=%d)\n", csv_error(&parser));
    }

    if (get_now(&t1) != 0) {
        fprintf(stderr, "time end failed\n");
        csv_free(&parser);
        fclose(fp);
        return 1;
    }

    // csv_free(&parser);
    fclose(fp);

    if (ok) {
        printf("well-formed\n");
    }
    printf("bytes_processed: %zu\n", total_bytes);
    printf("elapsed_ms: %lld\n", elapsed_ms_since(&t0, &t1));

    return ok ? 0 : 2;
}
